insert into categories (game_id, name) values
  ('truth-or-lie', 'วิทยาศาสตร์'),
  ('truth-or-lie', 'สัตว์โลก'),
  ('truth-or-lie', 'อาหาร'),
  ('truth-or-lie', 'ประวัติศาสตร์'),
  ('truth-or-lie', 'ร่างกายมนุษย์'),
  ('truth-or-lie', 'อวกาศ'),
  ('truth-or-lie', 'ประวัติศาสตร์ไทย'),
  ('truth-or-lie', 'เทคโนโลยี'),
  ('truth-or-lie', 'กีฬา'),
  ('truth-or-lie', 'ภูมิศาสตร์')
on conflict (game_id, name) do nothing;

with cat as (
  select id, name from categories where game_id = 'truth-or-lie'
)
insert into questions (game_id, category_id, text, answer, explain)
select 'truth-or-lie', cat.id, v.text, v.answer, v.explain
from (values
    ('วิทยาศาสตร์', 'เพชรเป็นแร่ที่แข็งที่สุดในโลกตามธรรมชาติ', true, 'จริง! เพชรมีความแข็งระดับ 10 บนมาตราโมส์ (Mohs scale) ซึ่งเป็นระดับสูงสุด'),
    ('วิทยาศาสตร์', 'น้ำมีความหนาแน่นสูงสุดที่อุณหภูมิ 0 องศาเซลเซียส', false, 'มั่ว! น้ำมีความหนาแน่นสูงสุดที่ 4 องศาเซลเซียส ไม่ใช่ 0 องศา ซึ่งเป็นเหตุผลที่น้ำแข็งลอยน้ำได้'),
    ('วิทยาศาสตร์', 'ปรอทเป็นโลหะชนิดเดียวที่เป็นของเหลวที่อุณหภูมิห้องปกติ', true, 'จริง! ปรอทมีจุดหลอมเหลวต่ำมาก ทำให้เป็นของเหลวที่อุณหภูมิห้อง ต่างจากโลหะอื่นๆ ทั่วไป'),
    ('วิทยาศาสตร์', 'เสียงเดินทางเร็วกว่าแสง', false, 'มั่ว! แสงเดินทางเร็วกว่าเสียงมาก แสงเดินทางด้วยความเร็วประมาณ 300,000 กม./วินาที ส่วนเสียงในอากาศแค่ราว 343 เมตร/วินาที'),
    ('วิทยาศาสตร์', 'ก๊าซฮีเลียมเบากว่าอากาศ', true, 'จริง! ฮีเลียมมีความหนาแน่นน้อยกว่าอากาศ จึงทำให้ลูกโป่งฮีเลียมลอยขึ้นได้'),
    ('วิทยาศาสตร์', 'น้ำแข็งลอยน้ำได้เพราะมีความหนาแน่นน้อยกว่าน้ำ', true, 'จริง! เมื่อน้ำแข็งตัว โมเลกุลจะจัดเรียงตัวห่างกันมากขึ้น ทำให้ความหนาแน่นลดลงและลอยน้ำได้'),
    ('วิทยาศาสตร์', 'ยางมะตอย (บิทูเมน) เป็นของแข็งที่ไม่มีวันไหลได้เลย', false, 'มั่ว! ยางมะตอยจริงๆ แล้วเป็นของเหลวหนืดมาก ไหลได้ช้ามากจนดูเหมือนของแข็ง มีการทดลอง ''Pitch Drop Experiment'' ที่พิสูจน์เรื่องนี้มาแล้วกว่า 90 ปี'),
    ('วิทยาศาสตร์', 'รุ้งกินน้ำเกิดจากการหักเหและสะท้อนของแสงผ่านหยดน้ำ', true, 'จริง! แสงอาทิตย์หักเหเมื่อผ่านเข้าไปในหยดน้ำ สะท้อนภายในหยดน้ำ แล้วหักเหออกมาอีกครั้ง ทำให้เกิดการแยกสีเป็นรุ้ง'),
    ('สัตว์โลก', 'นกฮัมมิงเบิร์ดสามารถบินถอยหลังได้', true, 'จริง! นกฮัมมิงเบิร์ดเป็นนกกลุ่มเดียวที่บินถอยหลังได้อย่างคล่องแคล่ว ด้วยการกระพือปีกเป็นรูปเลข 8'),
    ('สัตว์โลก', 'งูทุกชนิดมีพิษ', false, 'มั่ว! งูส่วนใหญ่ในโลกไม่มีพิษ มีเพียงประมาณ 600 ชนิดจากกว่า 3,000 ชนิดเท่านั้นที่มีพิษอันตรายต่อมนุษย์'),
    ('สัตว์โลก', 'แพนด้ายักษ์กินไผ่เป็นอาหารหลัก แม้ระบบย่อยอาหารจะเหมาะกับการกินเนื้อมากกว่า', true, 'จริง! แพนด้ามีระบบย่อยอาหารแบบสัตว์กินเนื้อ แต่ปรับพฤติกรรมมากินไผ่เป็นหลัก จึงต้องกินในปริมาณมากเพื่อให้ได้พลังงานพอ'),
    ('สัตว์โลก', 'ฉลามทุกชนิดต้องว่ายน้ำตลอดเวลา ไม่งั้นจะตาย', false, 'มั่ว! มีเพียงฉลามบางชนิดเท่านั้นที่ต้องว่ายน้ำตลอดเวลาเพื่อให้น้ำไหลผ่านเหงือก ฉลามหลายชนิดสามารถหยุดนิ่งและสูบน้ำผ่านเหงือกได้เอง'),
    ('สัตว์โลก', 'หมีขั้วโลกมีผิวหนังสีดำอยู่ใต้ขนสีขาว', true, 'จริง! ผิวหนังของหมีขั้วโลกเป็นสีดำเพื่อช่วยดูดซับความร้อนจากแสงอาทิตย์ ส่วนขนที่ดูขาวจริงๆ ไม่มีสีและโปร่งแสง'),
    ('สัตว์โลก', 'แมงมุมทุกชนิดสร้างใยได้', false, 'มั่ว! แมงมุมบางชนิด เช่น แมงมุมล่าเหยื่อ (wolf spider) ไม่สร้างใยดักเหยื่อ แต่ใช้วิธีไล่ล่าเหยื่อโดยตรงแทน'),
    ('สัตว์โลก', 'ช้างเป็นสัตว์บกที่มีขนาดใหญ่ที่สุดในโลก', true, 'จริง! ช้างแอฟริกาเป็นสัตว์บกที่มีน้ำหนักมากที่สุดในปัจจุบัน อาจหนักได้ถึง 6-7 ตัน'),
    ('สัตว์โลก', 'โลมาหลับโดยปิดสมองแค่ครึ่งซีกในแต่ละครั้ง', true, 'จริง! โลมามีการนอนหลับแบบ unihemispheric sleep คือหลับสมองทีละครึ่งซีก เพื่อให้ยังว่ายน้ำและหายใจได้ต่อเนื่อง'),
    ('อาหาร', 'วาซาบิที่เสิร์ฟในร้านซูชิส่วนใหญ่ทั่วโลก มักไม่ใช่วาซาบิแท้ แต่เป็นมัสตาร์ดผสมสีเขียว', true, 'จริง! วาซาบิแท้ปลูกยากและมีราคาแพงมาก ร้านอาหารทั่วไปส่วนใหญ่จึงใช้ฮอสแรดิชผสมมัสตาร์ดและสีผสมอาหารแทน'),
    ('อาหาร', 'ช็อกโกแลตขาวไม่มีส่วนผสมของโกโก้แข็ง (cocoa solids)', true, 'จริง! ช็อกโกแลตขาวทำจากเนยโกโก้ น้ำตาล และนม แต่ไม่มีโกโก้แข็งซึ่งเป็นส่วนที่ให้สีน้ำตาลและรสชาติช็อกโกแลตเข้มข้น'),
    ('อาหาร', 'กาแฟที่ระบุว่าไม่มีคาเฟอีน (decaf) ไม่มีคาเฟอีนอยู่เลย 0%', false, 'มั่ว! กาแฟ decaf ยังมีคาเฟอีนหลงเหลืออยู่เล็กน้อย เพียงแต่ถูกสกัดออกไปประมาณ 97% เท่านั้น ไม่ใช่ 100%'),
    ('อาหาร', 'ข้าวกล้องมีใยอาหารมากกว่าข้าวขาวเพราะยังมีเยื่อหุ้มเมล็ดอยู่', true, 'จริง! ข้าวกล้องผ่านการขัดสีน้อยกว่า จึงยังคงมีรำข้าวและจมูกข้าวที่อุดมด้วยใยอาหารและสารอาหารมากกว่าข้าวขาว'),
    ('อาหาร', 'มะพร้าวจัดเป็นถั่วตามหลักพฤกษศาสตร์', false, 'มั่ว! ตามหลักพฤกษศาสตร์ มะพร้าวจัดเป็นผลไม้ประเภท ''ดรุป'' (drupe) เช่นเดียวกับมะม่วงหรือลูกพีช ไม่ใช่ถั่ว'),
    ('อาหาร', 'น้ำผึ้งให้พลังงานต่อกรัมใกล้เคียงกับน้ำตาลทราย', true, 'จริง! ทั้งน้ำผึ้งและน้ำตาลทรายให้พลังงานประมาณ 3-4 กิโลแคลอรีต่อกรัมใกล้เคียงกัน แม้รสชาติและองค์ประกอบจะต่างกัน'),
    ('ประวัติศาสตร์', 'สงครามโลกครั้งที่ 1 เริ่มต้นในปี ค.ศ. 1914', true, 'จริง! สงครามโลกครั้งที่ 1 เริ่มขึ้นในเดือนกรกฎาคม ค.ศ. 1914 หลังการลอบสังหารอาร์ชดยุคฟรานซ์ เฟอร์ดินานด์'),
    ('ประวัติศาสตร์', 'คลีโอพัตราเป็นชาวอียิปต์โบราณโดยเชื้อสายทั้งหมด', false, 'มั่ว! คลีโอพัตราสืบเชื้อสายมาจากราชวงศ์ทอเลมีซึ่งมีต้นกำเนิดจากกรีซ ไม่ใช่ชาวอียิปต์พื้นเมืองโดยตรง'),
    ('ประวัติศาสตร์', 'กำแพงเบอร์ลินถูกทลายลงในปี ค.ศ. 1989', true, 'จริง! กำแพงเบอร์ลินถูกทลายลงเมื่อวันที่ 9 พฤศจิกายน ค.ศ. 1989 เป็นสัญลักษณ์ของการสิ้นสุดสงครามเย็น'),
    ('ประวัติศาสตร์', 'เรือไททานิคจมลงในการเดินทางครั้งแรก', true, 'จริง! เรือไททานิคชนภูเขาน้ำแข็งและจมลงในปี ค.ศ. 1912 ระหว่างการเดินทางครั้งแรก (maiden voyage) จากอังกฤษไปนิวยอร์ก'),
    ('ประวัติศาสตร์', 'พีระมิดแห่งกิซาถูกสร้างขึ้นโดยแรงงานทาสทั้งหมด', false, 'มั่ว! หลักฐานทางโบราณคดีสมัยใหม่ชี้ว่าพีระมิดถูกสร้างโดยแรงงานที่ได้รับค่าจ้างและอาหารเป็นส่วนใหญ่ ไม่ใช่ทาสตามความเชื่อเดิม'),
    ('ประวัติศาสตร์', 'จักรวรรดิโรมันตะวันตกล่มสลายก่อนจักรวรรดิโรมันตะวันออก (ไบแซนไทน์)', true, 'จริง! โรมันตะวันตกล่มสลายในปี ค.ศ. 476 ขณะที่จักรวรรดิไบแซนไทน์ยังคงอยู่ต่อมาอีกเกือบพันปีจนถึงปี ค.ศ. 1453'),
    ('ร่างกายมนุษย์', 'กระดูกที่เล็กที่สุดในร่างกายมนุษย์อยู่ในหู', true, 'จริง! กระดูกโกลนหรือ stapes ในหูชั้นกลางเป็นกระดูกที่เล็กที่สุดในร่างกายมนุษย์'),
    ('ร่างกายมนุษย์', 'ตับเป็นอวัยวะภายในที่สามารถงอกใหม่ได้บางส่วน', true, 'จริง! ตับมีความสามารถพิเศษในการงอกฟื้นฟูเนื้อเยื่อของตัวเองได้ แม้ถูกตัดออกไปมากถึง 70% ก็ยังงอกกลับมาได้'),
    ('ร่างกายมนุษย์', 'ลายนิ้วมือของคนในครอบครัวเดียวกันจะเหมือนกัน', false, 'มั่ว! ลายนิ้วมือเป็นเอกลักษณ์เฉพาะบุคคล แม้แต่ฝาแฝดแท้ที่มี DNA เหมือนกันก็ยังมีลายนิ้วมือที่ต่างกัน'),
    ('ร่างกายมนุษย์', 'หัวใจของมนุษย์อยู่กึ่งกลางหน้าอกพอดี', false, 'มั่ว! หัวใจอยู่ค่อนไปทางซ้ายของกึ่งกลางหน้าอกเล็กน้อย ไม่ได้อยู่ตรงกลางเป๊ะอย่างที่หลายคนเข้าใจ'),
    ('ร่างกายมนุษย์', 'คนเราสามารถมีชีวิตอยู่ได้โดยไม่มีม้าม', true, 'จริง! ม้ามไม่ใช่อวัยวะที่จำเป็นต่อการมีชีวิต หากถูกตัดออกไป ตับและอวัยวะอื่นจะทำหน้าที่ทดแทนได้บางส่วน แม้ภูมิคุ้มกันจะลดลงบ้าง'),
    ('ร่างกายมนุษย์', 'กระดูกเป็นเนื้อเยื่อที่ไม่มีเซลล์ที่มีชีวิตอยู่เลย', false, 'มั่ว! กระดูกเป็นเนื้อเยื่อที่มีชีวิต ประกอบด้วยเซลล์ที่คอยสร้างและซ่อมแซมกระดูกอยู่ตลอดเวลา ไม่ใช่วัตถุตายแข็งอย่างที่คิด'),
    ('อวกาศ', 'ดวงอาทิตย์เป็นดาวฤกษ์ขนาดกลางเมื่อเทียบกับดาวฤกษ์อื่นในจักรวาล', true, 'จริง! ดวงอาทิตย์จัดเป็นดาวฤกษ์ประเภท G ขนาดกลาง มีทั้งดาวฤกษ์ที่เล็กกว่าและใหญ่กว่ามากในจักรวาล'),
    ('อวกาศ', 'ดาวพลูโตถูกจัดให้เป็นดาวเคราะห์แคระตั้งแต่ปี 2006', true, 'จริง! สหพันธ์ดาราศาสตร์สากล (IAU) ปรับสถานะดาวพลูโตจากดาวเคราะห์เป็นดาวเคราะห์แคระในปี ค.ศ. 2006'),
    ('อวกาศ', 'อวกาศเป็นสุญญากาศสมบูรณ์แบบ ไม่มีอนุภาคใดๆ เลย', false, 'มั่ว! อวกาศมีอนุภาคอยู่เบาบางมาก เช่น ก๊าซและฝุ่นระหว่างดวงดาว จึงไม่ใช่สุญญากาศที่สมบูรณ์แบบ 100%'),
    ('อวกาศ', 'ดาวพฤหัสบดีเป็นดาวเคราะห์ที่ใหญ่ที่สุดในระบบสุริยะ', true, 'จริง! ดาวพฤหัสบดีมีขนาดใหญ่กว่าดาวเคราะห์อื่นทั้งหมดรวมกัน เป็นดาวเคราะห์ก๊าซยักษ์ที่ใหญ่ที่สุดในระบบสุริยะ'),
    ('อวกาศ', 'เราสามารถมองเห็นหลุมดำได้โดยตรงด้วยตาเปล่า', false, 'มั่ว! หลุมดำไม่ปล่อยแสงออกมา จึงมองไม่เห็นโดยตรง นักวิทยาศาสตร์ตรวจจับได้จากผลกระทบที่มีต่อสสารและแสงรอบๆ เท่านั้น'),
    ('อวกาศ', 'ดวงจันทร์แทบไม่มีชั้นบรรยากาศ ทำให้เสียงไม่สามารถเดินทางบนพื้นผิวได้', true, 'จริง! ดวงจันทร์มีชั้นบรรยากาศเบาบางมากจนแทบไม่มีเลย เสียงจึงไม่สามารถเดินทางผ่านได้เหมือนบนโลก'),
    ('ประวัติศาสตร์ไทย', 'กรุงศรีอยุธยาเป็นราชธานีของไทยนานกว่า 400 ปี', true, 'จริง! กรุงศรีอยุธยาเป็นราชธานีตั้งแต่ พ.ศ. 1893 ถึง พ.ศ. 2310 รวมเป็นเวลากว่า 417 ปี'),
    ('ประวัติศาสตร์ไทย', 'รัชกาลที่ 5 ทรงยกเลิกระบบทาสในไทย', true, 'จริง! พระบาทสมเด็จพระจุลจอมเกล้าเจ้าอยู่หัว (รัชกาลที่ 5) ทรงออกกฎหมายเลิกทาสอย่างค่อยเป็นค่อยไป จนสำเร็จสมบูรณ์ในปี พ.ศ. 2448'),
    ('ประวัติศาสตร์ไทย', 'ไทยไม่เคยตกเป็นอาณานิคมของชาติตะวันตกโดยตรง', true, 'จริง! ไทยเป็นประเทศเดียวในเอเชียตะวันออกเฉียงใต้ที่ไม่เคยตกเป็นอาณานิคมของชาติตะวันตกโดยตรง แม้จะต้องเสียดินแดนบางส่วนไปก็ตาม'),
    ('ประวัติศาสตร์ไทย', 'การเปลี่ยนแปลงการปกครอง พ.ศ. 2475 เปลี่ยนไทยจากสมบูรณาญาสิทธิราชย์เป็นประชาธิปไตยแบบมีพระมหากษัตริย์ภายใต้รัฐธรรมนูญ', true, 'จริง! คณะราษฎรก่อการเปลี่ยนแปลงการปกครองเมื่อวันที่ 24 มิถุนายน พ.ศ. 2475 เปลี่ยนระบอบการปกครองของไทยตั้งแต่นั้นมา'),
    ('ประวัติศาสตร์ไทย', 'จังหวัดเชียงใหม่เคยเป็นเมืองหลวงของอาณาจักรล้านนา', true, 'จริง! เชียงใหม่ก่อตั้งโดยพญามังรายเมื่อปี พ.ศ. 1839 และเป็นศูนย์กลางของอาณาจักรล้านนามาอย่างยาวนาน'),
    ('ประวัติศาสตร์ไทย', 'พระเจ้าตากสินทรงสถาปนากรุงธนบุรีเป็นราชธานีหลังกรุงศรีอยุธยาแตก', true, 'จริง! หลังกรุงศรีอยุธยาแตกในปี พ.ศ. 2310 สมเด็จพระเจ้าตากสินทรงกอบกู้เอกราชและสถาปนากรุงธนบุรีเป็นราชธานีแห่งใหม่'),
    ('เทคโนโลยี', 'อินเทอร์เน็ตกับเวิลด์ไวด์เว็บ (WWW) คือสิ่งเดียวกัน', false, 'มั่ว! อินเทอร์เน็ตคือโครงสร้างเครือข่ายทั่วโลก ส่วนเวิลด์ไวด์เว็บเป็นเพียงบริการหนึ่งที่ทำงานอยู่บนอินเทอร์เน็ตเท่านั้น'),
    ('เทคโนโลยี', 'ภาษาโปรแกรม Python ตั้งชื่อตามงูไพธอน', false, 'มั่ว! ผู้สร้างภาษา Python ตั้งชื่อตามรายการตลก Monty Python''s Flying Circus ที่เขาชื่นชอบ ไม่ใช่ตามชื่องู'),
    ('เทคโนโลยี', 'บลูทูธ (Bluetooth) ตั้งชื่อตามกษัตริย์ไวกิ้งในประวัติศาสตร์', true, 'จริง! ชื่อ Bluetooth มาจากกษัตริย์ Harald Bluetooth แห่งเดนมาร์กที่รวมชนเผ่าไวกิ้งให้เป็นหนึ่งเดียว เปรียบเทียบกับการรวมอุปกรณ์ให้สื่อสารกัน'),
    ('เทคโนโลยี', 'โดเมน .com ย่อมาจากคำว่า commercial', true, 'จริง! .com ย่อมาจาก commercial ถูกออกแบบมาให้ใช้กับเว็บไซต์เชิงพาณิชย์ตั้งแต่ยุคแรกของอินเทอร์เน็ต'),
    ('เทคโนโลยี', 'แบตเตอรี่ลิเธียมไอออนสามารถชาร์จซ้ำได้นับพันครั้ง', true, 'จริง! แบตเตอรี่ลิเธียมไอออนทั่วไปสามารถชาร์จซ้ำได้ราว 500-1,500 รอบขึ้นไป ก่อนที่ความจุจะเสื่อมลงอย่างเห็นได้ชัด'),
    ('เทคโนโลยี', 'คำว่า Wi-Fi เป็นคำย่อที่มีความหมายอย่างเป็นทางการว่า ''Wireless Fidelity''', false, 'มั่ว! Wi-Fi ไม่ได้เป็นคำย่อที่มีความหมายอย่างเป็นทางการ แต่เป็นชื่อทางการค้าที่บริษัทตั้งขึ้นให้ฟังดูดีและจดจำง่าย'),
    ('กีฬา', 'ฟุตบอลโลกจัดขึ้นทุก 4 ปี', true, 'จริง! ฟุตบอลโลก (FIFA World Cup) จัดขึ้นทุก 4 ปีมาตั้งแต่ปี ค.ศ. 1930 (ยกเว้นช่วงสงครามโลกครั้งที่ 2)'),
    ('กีฬา', 'โอลิมปิกฤดูร้อนและฤดูหนาวเคยจัดขึ้นในปีเดียวกันมาก่อน', true, 'จริง! ก่อนปี ค.ศ. 1994 โอลิมปิกฤดูร้อนและฤดูหนาวจัดในปีเดียวกัน ก่อนจะแยกให้สลับกันจัดทุก 2 ปีในเวลาต่อมา'),
    ('กีฬา', 'เทนนิสแกรนด์สแลมมีทั้งหมด 4 รายการ', true, 'จริง! แกรนด์สแลมเทนนิสมี 4 รายการคือ Australian Open, French Open, Wimbledon และ US Open'),
    ('กีฬา', 'มวยไทยเป็นกีฬาโอลิมปิกอย่างเป็นทางการแล้ว', false, 'มั่ว! แม้มวยไทยจะได้รับการรับรองจากคณะกรรมการโอลิมปิกสากล (IOC) แล้ว แต่ยังไม่เคยถูกบรรจุเป็นชนิดกีฬาแข่งขันในโอลิมปิกอย่างเป็นทางการ'),
    ('กีฬา', 'บาสเก็ตบอลถูกคิดค้นขึ้นในประเทศสหรัฐอเมริกา', true, 'จริง! เจมส์ ไนสมิธ คิดค้นกีฬาบาสเก็ตบอลขึ้นในปี ค.ศ. 1891 ที่รัฐแมสซาชูเซตส์ สหรัฐอเมริกา'),
    ('กีฬา', 'สนามฟุตบอลมาตรฐานทุกสนามต้องมีขนาดเท่ากันเป๊ะทั่วโลก', false, 'มั่ว! กฎของ FIFA อนุญาตให้สนามฟุตบอลมีขนาดแตกต่างกันได้ในช่วงที่กำหนด ไม่จำเป็นต้องเท่ากันเป๊ะทุกสนาม'),
    ('กีฬา', 'เหรียญทองโอลิมปิกทำจากทองคำบริสุทธิ์ 100%', false, 'มั่ว! เหรียญทองโอลิมปิกส่วนใหญ่ทำจากเงินแล้วชุบทองคำเพียงชั้นบางๆ เท่านั้น ไม่ใช่ทองคำบริสุทธิ์ทั้งเหรียญ'),
    ('ภูมิศาสตร์', 'แม่น้ำไนล์เป็นแม่น้ำที่ยาวที่สุดในโลก', true, 'จริง! แม่น้ำไนล์ในทวีปแอฟริกาได้รับการยอมรับโดยทั่วไปว่าเป็นแม่น้ำที่ยาวที่สุดในโลก ด้วยความยาวกว่า 6,600 กิโลเมตร'),
    ('ภูมิศาสตร์', 'ทวีปแอฟริกาเป็นทวีปที่มีจำนวนประเทศมากที่สุดในโลก', true, 'จริง! ทวีปแอฟริกามีประเทศทั้งหมด 54 ประเทศ มากกว่าทวีปอื่นใดในโลก'),
    ('ภูมิศาสตร์', 'ประเทศรัสเซียมีพื้นที่อยู่ในทวีปเอเชียมากกว่าทวีปยุโรป', true, 'จริง! ประมาณ 77% ของพื้นที่รัสเซียตั้งอยู่ในทวีปเอเชีย แม้ประชากรส่วนใหญ่จะอาศัยอยู่ในฝั่งยุโรปก็ตาม'),
    ('ภูมิศาสตร์', 'ทะเลเดดซี (Dead Sea) เป็นทะเลสาบน้ำจืด', false, 'มั่ว! ทะเลเดดซีเป็นแหล่งน้ำที่มีความเค็มสูงมากที่สุดแห่งหนึ่งในโลก เค็มกว่าน้ำทะเลทั่วไปหลายเท่า ไม่ใช่น้ำจืด'),
    ('ภูมิศาสตร์', 'ภูเขาเอเวอเรสต์เป็นภูเขาที่สูงที่สุดในโลกเมื่อวัดจากระดับน้ำทะเล', true, 'จริง! ยอดเขาเอเวอเรสต์สูง 8,849 เมตรจากระดับน้ำทะเล ถือเป็นจุดที่สูงที่สุดบนพื้นโลกเมื่อวัดแบบนี้'),
    ('ภูมิศาสตร์', 'ประเทศที่มีพื้นที่เล็กที่สุดในโลกคือนครรัฐวาติกัน', true, 'จริง! นครรัฐวาติกันมีพื้นที่เพียงประมาณ 0.44 ตารางกิโลเมตร ถือเป็นประเทศที่มีพื้นที่เล็กที่สุดในโลกที่ได้รับการรับรอง'),
    ('ภูมิศาสตร์', 'เส้นศูนย์สูตรพาดผ่านประเทศไทย', false, 'มั่ว! ประเทศไทยตั้งอยู่ในซีกโลกเหนือทั้งหมด ไม่มีส่วนใดที่เส้นศูนย์สูตรพาดผ่าน เส้นศูนย์สูตรอยู่ห่างลงไปทางใต้อีกหลายพันกิโลเมตร')
  ) as v(cat_name, text, answer, explain)
join cat on cat.name = v.cat_name
where not exists (
  select 1 from questions q2
  where q2.game_id = 'truth-or-lie' and q2.text = v.text
);